{"cards": [{"node_code": "N_1de714ed7a53a790", "definition": "研究同时具备多种货物吞吐能力或客货兼营功能的港口工程特征，涵盖多用途码头布局、通用装卸设施配置及综合防波体系设计。", "boundary": "本节点聚焦于“综合性”与“多功能性”的工程实现。边界在于区分“单一货种专用港”（如仅处理散货或油品）与“综合港”。若内容仅涉及客运或单一货种，应归入对应专用港节点。综合港强调设施的多适应性、分区规划及不同货种作业区的协调，而非单一功能的极致优化。", "includes": ["多用途码头结构与通用装卸设备选型", "综合港内不同货种作业区的空间布局与隔离", "兼顾多种船舶类型的泊位设计与防波要求"], "excludes": ["单一货种（如纯散货、纯油品）的专用工艺设计", "纯客运码头的专项设计（若未涉及综合布局）", "港口运营调度与物流管理"], "sibling_distinctions": [{"other_code": "N_131367b56c2b8c18", "rule": "综合港强调多货种兼容与通用设施，散货港侧重特定散货（如煤炭、矿石）的专用工艺与堆场设计。"}, {"other_code": "N_55ffe1540250cea0", "rule": "综合港侧重货物吞吐的多功能性，客货港侧重客运与货运功能的并存与分离，若以货运为主且多货种，归综合港；若强调旅客服务设施，归客货港。"}], "cross_boundary_rule": "若内容涉及综合港中某一特定货种（如集装箱）的专项优化，主挂载综合港，因整体布局受综合港约束；若完全脱离综合背景仅讨论该货种工艺，可关联对应货种港。"}, {"node_code": "N_55ffe1540250cea0", "definition": "研究同时承担旅客运输与货物运输功能的港口工程特征，涵盖客货分区布局、旅客服务设施工程及客货作业流程的空间协调。", "boundary": "本节点聚焦于“客货兼营”的工程布局与设施配置。边界在于区分“纯货运港”与“纯客运港”。若内容仅涉及货运设施，归入相应货种港；若仅涉及客运，可视为综合港或客货港的客运部分，但本节点强调两者的共存与接口。重点在于旅客候船设施、客运码头结构与货运区的安全隔离及交通组织。", "includes": ["客运码头结构与旅客候船厅工程设计", "客货分区布局原则及交通流线组织", "兼顾客货需求的泊位设计与防波设施"], "excludes": ["纯货运码头的专用工艺设计", "纯客运航线运营与票务管理", "单一货种（如散货、油品）的专用堆场设计"], "sibling_distinctions": [{"other_code": "N_1de714ed7a53a790", "rule": "客货港强调“人”与“货”的功能并存，综合港强调“多种货物”的功能并存。若港口以客运为显著特征且兼营货运，归客货港；若以多货种货运为主，归综合港。"}, {"other_code": "N_131367b56c2b8c18", "rule": "客货港包含客运功能，散货港仅涉及货物。若内容涉及旅客设施，不归散货港。"}], "cross_boundary_rule": "若内容涉及客货港中货运部分的散货工艺，主挂载客货港（因整体布局受客货协调约束），散货工艺细节可作为子项；若完全独立于客运背景，可关联散货港。"}, {"node_code": "N_131367b56c2b8c18", "definition": "研究以煤炭、矿石、粮食等散装货物为主要吞吐对象的港口工程特征，涵盖散货专用码头、堆场、输送系统及防污染设施设计。", "boundary": "本节点聚焦于“散装货物”的专用工程工艺。边界在于区分“件杂货”与“散货”。若内容涉及集装箱、车辆等件杂货，归入综合港或相应货种港。散货港强调连续装卸工艺、大容量堆场、皮带输送系统及粉尘/水污染控制，设施专用性强，通用性低于综合港。", "includes": ["散货专用泊位、卸船机及堆场工程设计", "散货输送系统（皮带、斗轮）与工艺布局", "散货港的防粉尘、防液体污染及环保设施"], "excludes": ["集装箱、车辆等件杂货的装卸工艺", "纯客运设施设计", "油品、液化气等液体散货的专用工艺（归油港）"], "sibling_distinctions": [{"other_code": "N_1de714ed7a53a790", "rule": "散货港侧重单一或少数几种散货的专用工艺，综合港侧重多货种兼容。若设施专为散货设计且无多货种通用性，归散货港。"}, {"other_code": "N_7abf1d726401ebcd", "rule": "散货港处理固体散装货物，油港处理液体/气体货物。两者在防污染要求上不同，固体散货侧重粉尘，油港侧重泄漏。"}], "cross_boundary_rule": "若内容涉及散货港中某种特定散货（如煤炭）的专项技术，主挂载散货港；若涉及散货与件杂货混合作业的布局，主挂载综合港。"}]}
